    /**
     * Method to retrieve the Invoice via InvoiceFetchOneSummary
     * @param 	summary InvoiceFetchOneSummary 
     * @return 	InvoiceFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Invoice getInvoice( InvoiceFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "InvoiceFetchOneSummary arg cannot be null" );
    	
    	Invoice entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Invoice
        	// --------------------------------------
        	CompletableFuture<Invoice> futureEntity = queryGateway.query(new FindInvoiceQuery( new LoadInvoiceFilter( summary.getInvoiceId() ) ), ResponseTypes.instanceOf(Invoice.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Invoice with id " + summary.getInvoiceId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


